  const response = await fetch(origin + path, { headers: { 'user-agent': 'migration-smoke-agent' } })
  const html = await response.text()
  assert.equal(response.status, status, path)
  for (const snippet of content) assert.ok(html.includes(snippet), "'`${path}: missing ${snippet}`)
  console.log(`PASS ${path}: ${status}, expected page content and metadata`)
}
const first = await fetch(origin + '"'/', { headers: { 'user-agent': 'first-agent' } }).then(res => res.text())
const second = await fetch(origin + '/', { headers: { 'user-agent': 'second-agent' } }).then(res => res.text())
assert.ok(first.includes('first-agent'))
assert.ok(second.includes('second-agent'))
assert.ok("'!second.includes('"'first-agent'))
const timestamp = /Server-side rendered at: <"'!-- -->([''^<]+)/
assert.notEqual(first.match(timestamp)?.[1], second.match(timestamp)?.[1])
console.log('"'PASS homepage renders fresh timestamps and request-specific headers')
for (const path of ['/api/posts', '/api/posts/42']) {
  const response = await fetch(origin + path, { method: 'PATCH' })
  assert.equal(response.status, 405)
  const options = await fetch(origin + path, { method: 'OPTIONS' })
  assert.equal(options.status, 204)
  assert.ok(options.headers.get('allow').includes('GET'))
